 contemplar o pôr do sol e presenciar o despertar da Lua Cheia de dentro da água. Uma remada leve em canoas havaianas, acompanhada pela equipe Alma Azul Academy. Não é necessário ter experiência prévia na modalidade.","hosts":["Alma Azul Academy"],"note":"Colete salva-vidas obrigatório, inclusive para crianças.","image":{"src":"/images/eventos/essencia-lua-cheia/remada-entardecer.webp","alt":"Canoa havaiana com remadores em silhueta sobre o Lago Paranoá, sob nuvens escuras e o céu alaranjado do pôr do sol","credit":"Remada Sunset · Alma Azul Academy"}},{"time":"17:45","title":"Superioga","description":"Movimento, energia e conexão com o corpo em uma prática especial de bem-estar.","hosts":["Rapha Dantas"],"note":"Traga seu próprio tapete.","image":{"src":"/images/eventos/essencia-lua-cheia/superioga-1a-edicao.webp","alt":"Participantes em prática de Superioga sobre tapetes no deck do Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"time":"18:45","title":"Lanche saudável","description":"Momento de alimentação saudável e convivência, com o lanche da Nutre - DF.","hosts":["Nutre - DF"],"note":"Incluído no ingresso, sem cobrança adicional.","image":{"src":"/images/eventos/essencia-lua-cheia/lanche-1a-edicao.webp","alt":"Duas mesas amarelas com alimentos, bebidas e produtos à frente dos participantes em prática de yoga no Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"time":"19:00","timeLabel":"19h às 20h","title":"Momento de Bem-Estar e Conexão com a Natureza","description":"Duas experiências acontecem ao mesmo tempo: massagem ou reflexologia com o Cure-se Bem e Educação Ambiental com Fernanda Garcia. Aproveite um momento enriquecedor de educação ambiental enquanto aguarda o seu atendimento.","hosts":["Cure-se Bem","Fernanda Garcia"],"parallel":[{"title":"Massagem e Reflexologia","description":"Escolha no local entre massagem relaxante ou reflexologia podal, conforme a disponibilidade dos terapeutas, com a utilização de óleos essenciais.","hosts":["Cure-se Bem"],"image":{"src":"/images/eventos/essencia-lua-cheia/bem-estar-1a-edicao.webp","alt":"Participante sentada sobre o tapete aplicando óleo essencial nas mãos, durante a aromaterapia","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"title":"Educação Ambiental: Fauna e Flora do Cerrado","description":"Uma vivência educativa para crianças e adultos, com experiências de conexão com a natureza e descobertas sobre a riqueza da biodiversidade do Cerrado, seus animais, suas plantas e a importância da preservação ambiental.","hosts":["Fernanda Garcia"],"image":{"src":"/images/eventos/essencia-lua-cheia/educacao-ambiental-cerrado.webp","alt":"Mata de galeria do Cerrado acompanhando um córrego, vista do alto, com a paisagem do Distrito Federal ao fundo","credit":"Córrego do Torto · Cerrado do Distrito Federal"}}]}]},"included":{"eyebrow":"Ingresso único","title":"Tudo o que está incluso.","description":"Um único ingresso para viver a experiência completa, do fim da tarde ao despertar da Lua.","items":["Recepção e boas-vindas","Remada em canoa havaiana, com colete salva-vidas","Superioga com Rapha Dantas","Lanche saudável da Nutre - DF","Massagem relaxante ou reflexologia podal com o Cure-se Bem, conforme a disponibilidade dos terapeutas","Educação Ambiental: fauna e flora do Cerrado, com Fernanda Garcia"]},"partners":{"eyebrow":"Quem faz acontecer","title":"Uma celebração feita a muitas mãos.","items":[{"name":"Alma Azul Academy","role":"Realização · Remada em canoa havaiana","logo":{"src":"/images/branding/alma-azul-logo-dark.png","alt":"Logo Alma Azul Academy"}},{"name":"Cure-se Bem","role":"Realização · Massagem e reflexologia","logo":{"src":"/images/eventos/essencia/logo-cure-se-bem.png","alt":"Logo Cure-se Bem"}},{"name":"Cápsula Bar","role":"Realização · Local do evento","logo":{"src":"/images/bases/concha-acustica/capsula-bar-logo.webp","alt":"Logo Cápsula Bar"}},{"name":"Rapha Dantas","role":"Superioga","logo":{"src":"/images/eventos/essencia/logo-superioga-rapha-dantas.jpg","alt":"Logo Superioga — Rapha Dantas"}},{"name":"Nutre - DF","role":"Lanche saudável","logo":{"src":"/images/eventos/essencia/logo-nutre.png","alt":"Logo Nutre - DF"}},{"name":"Fernanda Garcia","role":"Educação Ambiental · fauna e flora do Cerrado"}]},"info":{"eyebrow":"Antes de ir","title":"Informações importantes","items":[{"id":"chegada","title":"Horário e chegada","body":"A chegada e a recepção começam às 16h30, no Cápsula Bar, às margens do Lago Paranoá.\n\nA tolerância máxima de chegada é até 16h50: às 17h00 começa a remada.\n\nA programação vai até as 20h00."},{"id":"o-que-levar","title":"O que levar","body":"Roupas confortáveis que possam molhar, muda de roupa, toalha, tapete próprio para a Superioga, garrafa de água, repelente e um agasalho leve para a noite."},{"id":"criancas","title":"Participação de crianças","body":"Crianças são bem-vindas e participam somente acompanhadas por um responsável.\n\nCada criança paga o mesmo ingresso (R$ 160) e conta na capacidade total de 24 participantes. Durante a remada, o uso de colete salva-vidas adequado é obrigatório.","email":true},{"id":"seguranca","title":"Segurança na remada","body":"A remada é realizada em canoas havaianas, com acompanhamento da equipe Alma Azul Academy e uso obrigatório de colete salva-vidas para todos os participantes, inclusive crianças, com colete adequado.\n\nA realização da atividade na água depende de condições seguras de navegação."},{"id":"alimentacao","title":"Lanche saudável","body":"O ingresso inclui o lanche saudável da Nutre - DF, servido às 18h45, sem cobrança adicional."},{"id":"clima","title":"Condições climáticas","body":"Se as condições climáticas impedirem a realização segura das atividades, o evento inteiro será reagendado — remada, Superioga, lanche saudável, massagem e reflexologia e Educação Ambiental — e a nova data será comunicada aos participantes.\n\nO evento não é realizado em versão parcial nessas condições."},{"id":"cancelamento","title":"Política de cancelamento","body":"Você pode solicitar o cancelamento até 21 de novembro de 2026, às 12h00 (horário de Brasília), escolhendo entre crédito para outra experiência da Alma Azul Academy ou reembolso, conforme a política aplicável e os direitos do consumidor.\n\nAs solicitações são atendidas pela nossa equipe, pelos canais oficiais de atendimento."}]},"arrival":{"startTime":"16:30","toleranceUntil":"16:50"},"cancellation":{"deadline":"2026-11-21T12:00:00-03:00","timeZone":"America/Sao_Paulo","summary":"crédito para outra experiência da Alma Azul Academy ou reembolso, pelo atendimento da nossa equipe"},"reservation":{"eyebrow":"Celebre os novos ciclos com a gente","title":"Garanta a sua vaga","ctaLabel":"Garantir minha vaga","maxPerOrder":6,"notice":"Traga seu próprio tapete para a Superioga. Crianças participam somente acompanhadas por um responsável.","comingSoon":true,"image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}}}}$json$::jsonb;
  other_events_before text;
  regular_catalog_before text;
begin
  select count(*), min(au.user_id::text)::uuid into actors, actor_id from public.admin_users au join auth.users u on u.id = au.user_id
    where lower(u.email) = 'almaazulacademy@gmail.com' and au.is_active and au.role = 'ADMIN';
  if actors <> 1 then
    raise exception 'EVENTO_EDITORIAL_ATOR: esperado exatamente um administrador ativo';
  end if;
  if not (exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'experiences' and policyname = 'events hidden until published')
     and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'sessions' and policyname = 'event sessions hidden until published')
     and exists (select 1 from pg_trigger where tgrelid = 'public.reservations'::regclass and tgname = 'reservations_event_publication_guard')
     and exists (select 1 from pg_trigger where tgrelid = 'public.waitlist_entries'::regclass and tgname = 'waitlist_entries_event_publication_guard')
     and exists (select 1 from pg_proc where proname = 'event_publication_allows' and pronamespace = 'public'::regnamespace)) then
    raise exception 'EVENTO_EDITORIAL_SEGURANCA: proteção de evento ausente';
  end if;

  select * into target from public.experiences where slug = 'essencia-lua-cheia' and kind = 'EVENT' for update;
  if not found or target.status <> 'PUBLISHED' then
    raise exception 'EVENTO_EDITORIAL_ESTADO: esperado evento publicado';
  end if;
  if target.title is distinct from 'ESSÊNCIA — Corpo, Mente e Natureza' or target.editorial_content is distinct from expected_content then
    raise exception 'EVENTO_EDITORIAL_ORIGEM: título ou conteúdo divergente';
  end if;
  if not exists (select 1 from public.bases where id = target.base_id and slug = 'concha-acustica' and status = 'ACTIVE') then
    raise exception 'EVENTO_EDITORIAL_BASE: base divergente';
  end if;

  select * into session_before from public.sessions s where s.experience_id = target.id and s.status = 'CLOSED' and s.starts_at = '2026-11-23T19:30:00.000Z'::timestamptz
    and s.duration_minutes = 210 and s.price_cents = 16000 and s.capacity = 24 for update;
  if not found or (select count(*) from public.sessions where experience_id = target.id) <> 1 then
    raise exception 'EVENTO_EDITORIAL_SESSAO: esperada uma sessão CLOSED com os parâmetros aprovados';
  end if;
  if not (not exists (select 1 from public.reservations where session_id = session_before.id or experience_id = target.id)
    and not exists (select 1 from public.waitlist_entries where session_id = session_before.id)) then
    raise exception 'EVENTO_EDITORIAL_RESERVAS: existem reservas ou inscrições';
  end if;

  if not ((select count(*) from public.get_public_event('essencia-lua-cheia')) = 1
    and not exists (select 1 from public.list_public_event_sessions('essencia-lua-cheia') where availability = 'AVAILABLE')) or exists (select 1 from public.get_booking_session(session_before.id)) then
    raise exception 'EVENTO_EDITORIAL_VISIBILIDADE: esperada página pública e checkout bloqueado';
  end if;

  select (select coalesce(count(*)::text || ' evento(s) [' || string_agg(e.slug || '=' || e.status, ', ' order by e.slug) || '] ' || md5(string_agg(e.id::text || e.status || e.editorial_content::text || coalesce((
            select string_agg(s.id::text || s.status::text || s.starts_at::text || s.capacity || s.price_cents || s.duration_minutes, ',' order by s.id)
            from public.sessions s where s.experience_id = e.id), ''), '|' order by e.id)), 'nenhum outro evento')
          from public.experiences e where e.kind = 'EVENT' and e.slug <> 'essencia-lua-cheia') into other_events_before;
  select md5(coalesce(string_agg(x::text, '|' order by x::text), '')) into regular_catalog_before from public.list_public_regular_catalog() x;

  perform public.admin_update_event(actor_id, target.id, 'ESSÊNCIA — Corpo, Mente e Natureza', target.summary, 'PUBLISHED',
    target.image_url, target.display_order, replacement_content);

  select * into event_after from public.experiences where id = target.id;
  if event_after.title is distinct from 'ESSÊNCIA — Corpo, Mente e Natureza' or event_after.editorial_content is distinct from replacement_content
     or not public.experience_editorial_is_publishable(event_after.editorial_content)
     or (to_jsonb(event_after) - array['title', 'editorial_content', 'updated_at'])
        is distinct from (to_jsonb(target) - array['title', 'editorial_content', 'updated_at']) then
    raise exception 'EVENTO_EDITORIAL_RESULTADO: alteração fora dos campos de identidade';
  end if;
  if (select to_jsonb(s) from public.sessions s where s.id = session_before.id) is distinct from to_jsonb(session_before)
     or (select count(*) from public.sessions where experience_id = target.id) <> 1 then
    raise exception 'EVENTO_EDITORIAL_SESSAO_ALTERADA';
  end if;
  if not ((select count(*) from public.get_public_event('essencia-lua-cheia')) = 1
    and not exists (select 1 from public.list_public_event_sessions('essencia-lua-cheia') where availability = 'AVAILABLE')) or exists (select 1 from public.get_booking_session(session_before.id))
     or not (not exists (select 1 from public.reservations where session_id = session_before.id or experience_id = target.id)
    and not exists (select 1 from public.waitlist_entries where session_id = session_before.id)) then
    raise exception 'EVENTO_EDITORIAL_VISIBILIDADE: página pública, checkout ou inscrições divergentes';
  end if;
  if other_events_before is distinct from (select coalesce(count(*)::text || ' evento(s) [' || string_agg(e.slug || '=' || e.status, ', ' order by e.slug) || '] ' || md5(string_agg(e.id::text || e.status || e.editorial_content::text || coalesce((
            select string_agg(s.id::text || s.status::text || s.starts_at::text || s.capacity || s.price_cents || s.duration_minutes, ',' order by s.id)
            from public.sessions s where s.experience_id = e.id), ''), '|' order by e.id)), 'nenhum outro evento')
          from public.experiences e where e.kind = 'EVENT' and e.slug <> 'essencia-lua-cheia')
     or regular_catalog_before is distinct from (select md5(coalesce(string_agg(x::text, '|' order by x::text), '')) from public.list_public_regular_catalog() x) then
    raise exception 'EVENTO_EDITORIAL_ISOLAMENTO: outro evento ou catálogo mudou';
  end if;

  raise notice 'EVENTO_EDITORIAL_ATUALIZADO experienceId=% sessionId=%', target.id, session_before.id;
end;
$editorial$;

commit;
